mapper.select:
select `f`.*,us.real_name as send_real_name, us.image_url, ur.real_name as receive_real_name from `friend_message` f   left join `user` us on f.send_user_id = us.id
   left join `user` ur on f.receive_user_id = ur.id
   where 1=1
    
        and f.send_user_id = #{sendUserId}
    
    
        and f.receive_user_id = #{receiveUserId}
    
    
        and f.type = #{type}
    
    
        and f.status = #{status}
    
    
        and us.real_name like concat('%',#{sendRealName},'%')
    
            
        and ur.real_name like concat('%',#{receiveRealName},'%')
    
    order by f.create_time desc
